DECLARE
  paquete jsonb := $polo${"ley":{"id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","siglas":"PODECOBI-SEYBAPLAYA-I","titulo":"ACUERDO por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Seybaplaya I, Campeche.","tipo":"acuerdo","fecha_publicacion":"2025-06-30","url_original":"https://sidof.segob.gob.mx/notas/docFuente/5761459","temas_clave":["PODECOBI","Declaratoria","Seybaplaya I","Campeche"]},"articulos":[{"id":"9013f2de-5439-5342-9bb6-70e724c8f91a","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Preámbulo y considerandos","contenido":"<p>ACUERDO por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Seybaplaya I, Campeche.</p>\n<p>Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Economía.</p>\n<p>MARCELO LUIS EBRARD CASAUBON, Secretario de Economía, con fundamento en los artículos 34 de la Ley Orgánica de la Administración Pública Federal; Primero, segundo párrafo, Décimo, tercer párrafo del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar; 5, fracciones XVII y XXIV, del Reglamento Interior de la Secretaría de Economía, y los lineamientos 2 fracción XIV, 4, fracción II, 8, segundo párrafo, del Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar y</p>\n<p>CONSIDERANDO</p>\n<p>Que de conformidad con lo dispuesto en los artículos 25 y 26, apartado A de la Constitución Política de los Estados Unidos Mexicanos, corresponde al Estado la rectoría del desarrollo nacional mediante la competitividad, el fomento del crecimiento económico, el empleo, así como una justa distribución del ingreso y la riqueza, para garantizar que ésta sea integral y sustentable y que permita el pleno ejercicio de la libertad y la dignidad de los individuos, grupos y clases sociales. Al desarrollo económico nacional concurrirán, con responsabilidad social, el sector público, el sector social y el sector privado, sin menoscabo de otras formas de actividad económica que contribuyan al desarrollo de la Nación;</p>\n<p>Que el Plan Nacional de Desarrollo(1) 2025-2030, publicado en el Diario Oficial de la Federación (DOF) el 15 de abril de 2025, considera al \"Plan México\" como una herramienta de largo plazo que sustenta una estrategia de industrialización en el país incrementando la participación de empresas mexicanas en la cadena de proveeduría de las exportaciones y en la generación de productos para consumo nacional; permitiendo a las empresas nacionales, desde micro, pequeñas y medianas hasta grandes corporaciones, tener un papel más activo en la manufactura de bienes intermedios, insumos y componentes esenciales;</p>\n<p>Que en ese sentido el \"Plan México\", presentado por la Presidenta de los Estados Unidos Mexicanos el 13 de enero de 2025, es una estrategia de desarrollo nacional que busca fortalecer el mercado interno y los mercados regionales para posicionar a México entre las diez principales economías del mundo y reducir la pobreza y la desigualdad. Esta estrategia también busca promover el desarrollo económico sostenible y equitativo en todo el país; generar empleos dignos y bien remunerados; fortalecer el progreso científico, tecnológico y la innovación; ampliar el acceso a la educación media superior y superior y su vínculo con el Plan Nacional de Desarrollo, a fin de alcanzar el bienestar de las mexicanas y los mexicanos;</p>\n<p>Que el 22 de mayo de 2025, se publicó en el DOF el \"Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar\"; en el cual se brindan beneficios tributarios a los contribuyentes que realicen actividades económicas productivas al interior de los Polos de Desarrollo Económico para el Bienestar y a las personas morales que hayan obtenido Autorización que los acredite como Desarrolladores;</p>\n<p>Que, en la misma fecha, se publicó en el DOF el Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar;</p>\n<p>Que en la sesión del Comité Intersecretarial de Promoción celebrada el 9 de junio de 2025, fue aprobado el Dictamen Colegiado correspondiente al Polo de Desarrollo para el Bienestar Seybaplaya I, del estado de Campeche, y</p>\n<p>Que con el objetivo de impulsar la competitividad y favorecer la operación de los contribuyentes que realicen actividades económicas productivas al interior de los Polos de Desarrollo Económico para el Bienestar y de los Desarrolladores, así como en el ejercicio de la facultad establecida en el artículo 34 de la Ley Orgánica de la Administración Pública Federal, he tenido a bien expedir el siguiente</p>\n<p>ACUERDO POR EL QUE SE EMITE LA DECLARATORIA DEL POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR SEYBAPLAYA I, CAMPECHE</p>","tipo_articulo":"preambulo","orden":1,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"53926dda-2564-5994-a426-8bf15ca6bbaa","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo primero","contenido":"<p>ARTÍCULO PRIMERO. El presente Acuerdo tiene por objeto declarar como Polo de Desarrollo Económico para el Bienestar Seybaplaya I, Campeche, al polígono que se describe en el artículo siguiente.</p>","tipo_articulo":"ordinario","orden":2,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"dc1ea51b-86de-5241-9f7f-06cddfe83477","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo segundo","contenido":"<p>ARTÍCULO SEGUNDO. Se declara como POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR SEYBAPLAYA I, CAMPECHE (PODECOBI SEYBAPLAYA I), a la superficie de 99-98-97.42 263-16-81.106 hectáreas (NOVENTA Y NUEVE HECTÁREAS, NOVENTA Y OCHO ÁREAS, NOVENTA Y SIETE Y CUARENTA Y DOS CENTIÁREAS), ubicado en el municipio de Seybaplaya, estado de Campeche de conformidad con los cuadros de construcción y el croquis de ubicación siguientes:</p>\n<table><thead><tr><th colspan=\"7\">CUADRO DE CONSTRUCCIÓN FRACCIÓN 1</th></tr><tr><th colspan=\"2\">LADO</th><th rowspan=\"2\">RUMBO</th><th rowspan=\"2\">DISTANCIA</th><th rowspan=\"2\">PV</th><th colspan=\"2\">COORDENADAS</th></tr><tr><th>EST</th><th>PV</th><th>X</th><th>Y</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td>1</td><td>743986.247</td><td>2175766.681</td></tr><tr><td>1</td><td>2</td><td>N 7-54-1 E</td><td>761.682</td><td>2</td><td>744090.938</td><td>2176521.134</td></tr><tr><td>2</td><td>3</td><td>S 62-20-31 E</td><td>424.788</td><td>3</td><td>744467.187</td><td>2176323.959</td></tr><tr><td>3</td><td>4</td><td>S 9-5-19 W</td><td>552.785</td><td>4</td><td>744379.869</td><td>2175778.104</td></tr><tr><td>4</td><td>1</td><td>S 88-20-16 W</td><td>393.788</td><td>1</td><td>743986.247</td><td>2175766.681</td></tr><tr><td colspan=\"7\">SUPERFICIE: 25-91-82.42 Ha</td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td colspan=\"7\">CUADRO DE CONSTRUCCIÓN FRACCIÓN 2</td></tr><tr><td colspan=\"2\">LADO</td><td rowspan=\"2\">RUMBO</td><td rowspan=\"2\">DISTANCIA</td><td rowspan=\"2\">PV</td><td colspan=\"2\">COORDENADAS</td></tr><tr><td>EST</td><td>PV</td><td>X</td><td>Y</td></tr><tr><td></td><td></td><td></td><td></td><td>1</td><td>743986.247</td><td>2175766.68</td></tr><tr><td>1</td><td>2</td><td>S 88-20-15 W</td><td>351.813</td><td>2</td><td>743634.582</td><td>2175756.48</td></tr><tr><td>2</td><td>3</td><td>S 88-15-51 W</td><td>192.169</td><td>3</td><td>743442.501</td><td>2175750.65</td></tr><tr><td>3</td><td>4</td><td>S 88-15-51 W</td><td>212.728</td><td>4</td><td>743229.871</td><td>2175744.21</td></tr><tr><td>4</td><td>5</td><td>S 88-15-51 W</td><td>563.91</td><td>5</td><td>742666.22</td><td>2175727.13</td></tr><tr><td>5</td><td>6</td><td>N 1-23-45 E</td><td>5.912</td><td>6</td><td>742666.364</td><td>2175733.04</td></tr><tr><td>6</td><td>7</td><td>N 21-23-31 E</td><td>15.381</td><td>7</td><td>742671.974</td><td>2175747.36</td></tr><tr><td>7</td><td>8</td><td>N 47-10-19 E</td><td>116.858</td><td>8</td><td>742757.677</td><td>2175826.8</td></tr><tr><td>8</td><td>9</td><td>N 6-25-58 E</td><td>56.812</td><td>9</td><td>742764.042</td><td>2175883.25</td></tr><tr><td>9</td><td>10</td><td>N 9-22-32 W</td><td>156.872</td><td>10</td><td>742738.487</td><td>2176038.03</td></tr><tr><td>10</td><td>11</td><td>N 25-52-40 W</td><td>70.498</td><td>11</td><td>742707.718</td><td>2176101.46</td></tr><tr><td>11</td><td>12</td><td>N 71-36-0 E</td><td>526.454</td><td>12</td><td>743207.258</td><td>2176267.63</td></tr><tr><td>12</td><td>13</td><td>N 66-46-45 E</td><td>14.52</td><td>13</td><td>743220.602</td><td>2176273.36</td></tr><tr><td>13</td><td>14</td><td>N 73-46-33 E</td><td>828.367</td><td>14</td><td>744015.98</td><td>2176504.8</td></tr><tr><td>14</td><td>15</td><td>N 77-42-28 E</td><td>76.717</td><td>15</td><td>744090.938</td><td>2176521.13</td></tr><tr><td>15</td><td>1</td><td>S 7-54-1 W</td><td>761.682</td><td>1</td><td>743986.247</td><td>2175766.68</td></tr><tr><td colspan=\"7\">SUPERFICIE: 74-07-15.05 Ha</td></tr></tbody></table>\n<p><a href=\"https://dof.gob.mx/abrirPDF.php?anio=2025&amp;archivo=30062025-MAT.pdf&amp;repo=#page=40\">Croquis de ubicación en el PDF oficial · página 40</a></p>","tipo_articulo":"ordinario","orden":3,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"1576f67d-2537-5d89-9fdc-8a373eb862ec","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero","contenido":"<p>ARTÍCULO TERCERO. La superficie a que se refiere el artículo anterior cumple los criterios de selección establecidos en el Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, publicado en el Diario Oficial de la Federación el 22 de mayo de 2025, como a continuación se señalan:</p>","tipo_articulo":"ordinario","orden":4,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"9d6636f7-60d4-5b81-91a0-2950ebf794e9","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · I. Criterio de Macro Localización","contenido":"<p>I. Criterio de Macro Localización:</p>\n<p>La superficie del PODECOBI SEYBAPLAYA I, se ubica en el municipio de Seybaplaya, estado de Campeche, en la región centro-litoral del estado, a 29 kilómetros al suroeste de la ciudad capital, San Francisco de Campeche, de conformidad con los cuadros de construcción y el croquis de ubicación referidos en el artículo anterior. Los municipios aledaños son: Campeche y Champotón.</p>","tipo_articulo":"ordinario","orden":5,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"ed0899cb-1503-589d-ba3e-21253fa913ab","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · II. Criterio de Comunicación y Conectividad","contenido":"<p>II. Criterio de Comunicación y Conectividad:</p>\n<p>La superficie del PODECOBI SEYBAPLAYA I se encuentra a pie de la Carretera Federal MEX-180, a 4.9 km del Puerto de Seybaplaya y a 29 km del Puerto de Campeche. La distancia al Aeropuerto Internacional de Campeche es de 36 km y a 37 km de la vía férrea del Tren Maya. Esta ubicación le permite una conectividad potencial hacia mercados nacionales e internacionales. Su proximidad a la actividad industrial logística de Campeche y Mérida, podría integrar la zona en un corredor regional.</p>","tipo_articulo":"ordinario","orden":6,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"cfcd1c24-7a8f-5d10-9094-e370197cacd4","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · III. Criterio Poblacional","contenido":"<p>III. Criterio Poblacional:</p>\n<p>Conforme al Censo de Población y Vivienda 2020(2), la población total de los municipios mencionados en el párrafo anterior es mayor a 50,000 habitantes.</p>\n<table><thead><tr><th>Municipio Sede y Municipios Aledaños</th><th>Población Censo 2020</th><th>Población total</th></tr></thead><tbody><tr><td>Campeche</td><td>294,077</td><td rowspan=\"3\">387,544</td></tr><tr><td>Champotón</td><td>78,170</td></tr><tr><td>Seybaplaya</td><td>15,297</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":7,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"1a8aaa36-f0dd-5896-a708-b48b63765163","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · IV. Criterio de Factibilidad Social","contenido":"<p>IV. Criterio de Factibilidad Social:</p>\n<p>El Instituto Nacional de los de los Pueblos Indígenas, a través del oficio núm. CGDI/2025/OF/582 de fecha 06 de junio de 2025, informó que \"(...) En el caso concreto, de una revisión de los archivos para georreferenciación del proyecto, no se ubican localidades ni núcleos agrarios certificados dentro de la superficie del proyecto (...)</p>\n<p>...</p>\n<p>Por lo tanto, al no identificarse comunidad indígena titular del Derecho a la Consulta, resulta innecesario analizar si la medida que nos ocupa puede generar posibilidad de afectación y menos aún determinar la procedencia de un proceso de consulta previa, libre e informada por posible afectación a sus derechos territoriales. (...)\"</p>","tipo_articulo":"ordinario","orden":8,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"af505e8a-1e7e-50a2-813b-e43557e567af","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · V. Criterio Educativo","contenido":"<p>V. Criterio Educativo:</p>\n<p>En el PODECOBI SEYBAPLAYA I, y los municipios aledaños a este, se localizan las siguientes instituciones de educación media superior y superior:</p>\n<table><thead><tr><th>INSTITUCIONES DE EDUCACIÓN SUPERIOR</th></tr></thead><tbody><tr><td>Champotón</td></tr><tr><td>Instituto Tecnológico Superior de Champotón</td></tr><tr><td>Instituto de Estudios Superiores de Campeche</td></tr><tr><td>San Francisco de Campeche</td></tr><tr><td>Centro de Actualización del Magisterio</td></tr><tr><td>Escuela Judicial del Estado de Campeche</td></tr><tr><td>Instituto Campechano</td></tr><tr><td>Instituto de Estudios en Derechos Humanos</td></tr><tr><td>Instituto Tecnológico de Lerma</td></tr><tr><td>Normal Superior del Estado de Campeche \"Brígido A. Redondo Domínguez\"</td></tr><tr><td>Universidad Autónoma De Campeche</td></tr><tr><td>Universidad Pedagógica Nacional Núm. 041 María Lavalle Urbina</td></tr><tr><td>Centro de Estudios Clínica e Investigación Psicológica</td></tr><tr><td>Centro de Estudios Superiores del Sureste Campus Campeche</td></tr><tr><td>Centro de Terapia Familiar y de Pareja</td></tr><tr><td>Centro Universitario Metropolitano de Campeche</td></tr><tr><td>Colegio Universitario Internacional Baluartes</td></tr><tr><td>Instituto de Estudios Superiores Simón Bolívar</td></tr><tr><td>Instituto de Estudios Universitarios del Estado de Campeche</td></tr><tr><td>Instituto Humanista de Estudios Superiores</td></tr><tr><td>Instituto Pedagógico Campechano María de la Luz Ortega de Ruiz</td></tr><tr><td>Instituto superior de Filosofía Santo Tomas de Aquino</td></tr><tr><td>Instituto Universitario del Centro de México Campus Campeche</td></tr><tr><td>Instituto Tecnológico De Estudios Superiores Rene Descartes</td></tr><tr><td>Universidad del MAYAB Campus Campeche</td></tr><tr><td>Universidad Fray Angélico</td></tr><tr><td>Universidad Guadalupe victoria</td></tr><tr><td>Universidad Hispanoamericana Justo Sierra</td></tr><tr><td>Universidad hispanoamericana para el Desarrollo</td></tr><tr><td>Universidad Mundo Maya Campus Campeche</td></tr><tr><td>Universidad Sor Juana Inés de la Cruz</td></tr><tr><td>Universidad Valle del Grijalva, Campus Campeche</td></tr><tr><td>Universidad Vizcaya de las Américas</td></tr></tbody></table>\n<table><thead><tr><th>INSTITUCIONES DE EDUCACIÓN MEDIA SUPERIOR</th></tr></thead><tbody><tr><td>Seybaplaya</td></tr><tr><td>Colegio de Bachilleres Plantel 04 Seybaplaya</td></tr><tr><td>Champotón</td></tr><tr><td>Centro de Atención para Estudiantes con Discapacidad CETIS 082</td></tr><tr><td>Centro de Estudios Tecnológicos Industrial y de Servicios Num.82</td></tr><tr><td>Colegio de Bachilleres Plantel 09 Champotón</td></tr><tr><td>Escuela Preparatoria Nocturna Champotón</td></tr><tr><td>San Francisco de Campeche</td></tr><tr><td>Bachillerato Tecnológico de Educación y Promoción Deportiva (BTED)</td></tr><tr><td>Colegio de Estudios Científicos y Tecnológicos del Estado de Campeche, Concordia (CECYTEC)</td></tr><tr><td>Centro de Bachillerato Tecnológico Industrial y de Servicios Núm. 9</td></tr><tr><td>Centro de Estudios Tecnológicos del Mar Núm. 02</td></tr><tr><td>Escuela Preparatoria del Instituto Campechano</td></tr><tr><td>Escuela Preparatoria Dr. Nazario Víctor Montejo Godoy</td></tr><tr><td>Escuela Preparatoria Estatal por Cooperación Fernando E. Angil Lara</td></tr><tr><td>Escuela Preparatoria Lic. Guillermo Gonzales Galera</td></tr><tr><td>Subsistema Preparatoria Abierta</td></tr><tr><td>Centro Educativo XAIL SC</td></tr><tr><td>Colegio Campeche</td></tr><tr><td>Colegio Leones</td></tr><tr><td>Colegio Mundo Maya</td></tr><tr><td>Escuela de Puericultura del Sureste Dr. Manuel Acevedo Ruiz del Hoyo Plantel Campeche</td></tr><tr><td>Escuela Preparatoria Particular Miguel Hidalgo</td></tr><tr><td>Fórum de las Américas Preparatoria</td></tr><tr><td>Instituto Ah-Kim-Pech</td></tr><tr><td>Instituto Comercial Bancario Apolinar AC</td></tr><tr><td>Instituto Morelos</td></tr><tr><td>Liceo Amaya</td></tr><tr><td>Preparatoria Antonio Canto</td></tr><tr><td>Preparatoria CUME</td></tr><tr><td>Preparatoria Fray Angélico</td></tr><tr><td>Preparatoria Salvador Vélez</td></tr><tr><td>Preparatoria Septimio Pérez Palacios</td></tr><tr><td>Preparatoria Simón Bolívar</td></tr><tr><td>Universidad ANAHUAC, Bachillerato Cumbres Campeche</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":9,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"8fbebd78-a205-53ea-9abd-157b697b25ce","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · VI. Criterio Territorial","contenido":"<p>VI. Criterio Territorial:</p>\n<p>Es una zona con alto potencial agroindustrial y logístico, su ubicación estratégica frente al Golfo de México, su conexión con redes de carga y transporte para facilitar el traslado de mercancías y su cercanía a proyectos del Corredor Interoceánico son puntos relevantes de este polo. Debido a su potencial logístico-portuario, se valora positivamente su articulación con el Tren Maya y proyectos de desarrollo agroindustrial y otras industrias ligeras claves, para impulsar encadenamientos productivos y desarrollo económico.</p>\n<p>Para el desarrollo de actividades productivas en el PODECOBI SEYBAPLAYA I son vocaciones productivas, prioritarias y potenciales las siguientes:</p>\n<p>· Logística</p>\n<p>· Agroindustria</p>\n<p>· Manufactura ligada a la industria energética</p>\n<p>· Otras industrias ligeras.</p>","tipo_articulo":"ordinario","orden":10,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"63dae552-467d-5ba3-a46a-8488793b816c","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · VII. Criterio de Factibilidad Industrial","contenido":"<p>VII. Criterio de Factibilidad Industrial:</p>\n<p>El inmueble destinado al PODECOBI SEYBAPLAYA I fue declarado como Polo Industrial del Bienestar por el Gobierno del estado de Campeche mediante Acuerdo del Ejecutivo de dicha entidad con fecha 25 de septiembre de 2024, publicado en el Periódico Oficial de la entidad.</p>","tipo_articulo":"ordinario","orden":11,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"7f1405ca-bbde-53fe-8093-e3c04494fd93","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · VIII. Criterio de Sostenibilidad","contenido":"<p>VIII. Criterio de Sostenibilidad:</p>\n<p>Conforme al dictamen individual de la Secretaría de Medio Ambiente y Recursos Naturales, de fecha 3 de junio, con número de oficio SDSEC/800/79/2025 el \"PODECOBI SEYBAPLAYA I, CAMPECHE, es viable en materia ambiental, sujeto al cumplimiento de los requisitos normativos aplicables y a la integración de medidas específicas para protección ecológica y gestión hídrica\". Asimismo, \"no se localiza dentro de Áreas Naturales Protegidas ni de tierras de pueblos indígenas\".</p>","tipo_articulo":"ordinario","orden":12,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"1beaf360-0462-5666-b338-d39b08a2cf58","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · IX. Criterio de Servicios e Infraestructura","contenido":"<p>IX. Criterio de Servicios e Infraestructura:</p>\n<p>El predio se localiza cerca del paso del Tren Maya y de la carretera 180. La infraestructura disponible dentro del predio incluye gas y electricidad.</p>","tipo_articulo":"ordinario","orden":13,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"41885e9b-96f4-5dd0-8a6e-946a4f9df0c9","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo tercero · X. Criterio de Propiedad","contenido":"<p>X. Criterio de Propiedad:</p>\n<p>De conformidad con la información proporcionada por la entidad federativa y la documentación que fue puesta a disposición del Comité Intersecretarial de Promoción, se desprende que los predios que conforman el área destinada al Polo de Desarrollo para el Bienestar Seybaplaya I, Campeche, son de propiedad pública estatal.</p>","tipo_articulo":"ordinario","orden":14,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"2f297df6-a68d-52f3-a750-cecd614268d4","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Artículo cuarto","contenido":"<p>ARTÍCULO CUARTO. El estado de Campeche y la Secretaría de Economía deberán suscribir el convenio de coordinación a que se refiere el artículo Décimo, párrafo tercero del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar.</p>","tipo_articulo":"ordinario","orden":15,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"971bde45-9722-59db-8915-bad834d028f7","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Transitorio único","contenido":"<p>TRANSITORIO</p>\n<p>ÚNICO. La presente Declaratoria entrará en vigor el día siguiente al de su publicación en el Diario Oficial de la Federación.</p>","tipo_articulo":"transitorio","orden":16,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"6366afc0-987b-560d-993c-3759a6a5ef86","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Firma del acuerdo","contenido":"<p>Ciudad de México, a diecinueve de junio de 2025.- El Secretario de Economía, Marcelo Luis Ebrard Casaubon.- Rúbrica.</p>","tipo_articulo":"complementario","orden":17,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"e8dc81d9-4446-5598-86a5-1e4b7e1023c1","ley_id":"641a8b80-a2d7-52c5-9844-2d83570eaf4d","identificador":"Notas al pie","contenido":"<p>1 https://www.gob.mx/cms/uploads/attachment/file/981072/PND_2025-2030_v250226_14.pdf</p>\n<p>2 Inegi (2020). Censo de Población y Vivienda 2020. Instituto Nacional de Estadística y Geografía (INEGI). https://www.inegi.org.mx/</p>","tipo_articulo":"nota","orden":18,"titulo_nombre":"Seybaplaya I","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null}]}$polo$::jsonb;
  ley jsonb := paquete->'ley';
  ley_uuid uuid := (ley->>'id')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(ley->>'url_original', 0));
  IF EXISTS (SELECT FROM public.leyes WHERE id <> ley_uuid AND (siglas = ley->>'siglas' OR url_original = ley->>'url_original')) THEN
    RAISE EXCEPTION 'Declaratoria registrada con otro ID: %', ley->>'siglas';
  END IF;
  INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave)
  SELECT id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave FROM jsonb_populate_record(null::public.leyes, ley)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.articulos (id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre)
  SELECT id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre
  FROM jsonb_populate_recordset(null::public.articulos, paquete->'articulos') ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT FROM public.leyes l WHERE l.id = ley_uuid AND to_jsonb(l) @> ley)
     OR EXISTS (SELECT FROM jsonb_array_elements(paquete->'articulos') a WHERE NOT EXISTS (
       SELECT FROM public.articulos t WHERE t.id = (a->>'id')::uuid AND to_jsonb(t) @> a)) THEN
    RAISE EXCEPTION 'El registro existente difiere del cotejo de %', ley->>'siglas';
  END IF;
END
$carga$;
